SourceCode.Declaration:
[TFMListElementAttribute('row')]
class TFMListRow extends TFMListBase
{
    TFMListColumns columns;

}

Method.Source:
public static TFMListRow Construct()
{
    return new TFMListRow();
}

/// <summary>
/// Constructs and adds the column to the row.
/// </summary>
/// <param name = "_width"></param>
/// <returns></returns>
public TFMListColumn makeColumn(TFMListWidth _width = 0)
{
    TFMListColumn column = TFMListColumn::Construct(_width);
    this.addColumn(column);
    return column;
}

/// <summary>
/// Helper method to add a column to a row.
/// </summary>
/// <param name = "_column"></param>
public void addColumn(TFMListColumn _column)
{
    if(!columns)
    {
        columns = new TFMListColumns();
        baseChildren.insert(baseChildren.elements(),columns);
    }
    columns.addChild(_column);
}

public void addChild(Object _child)
{
    if(_child is TFMListColumns)
    {
        columns = _child;
    }
    baseChildren.insert(baseChildren.elements(),_child);
}
